@js:
function trimSlash(s) {
  s = String(s);
  while (s.length > 0 && s.charAt(s.length - 1) === "/") s = s.substring(0, s.length - 1);
  return s;
}
var SITES = {
  "一夜春宵": "https://example.com",
  "春晓阁": "https://example.com",
  "肉文网": "https://example.com",
  "笔趣阁": "https://example.com"
};
var sn = String(cache.get("siteName") || "一夜春宵");
var v = source.getVariable();
var base = trimSlash(SITES[sn] || SITES["一夜春宵"]);
if (v) {
  v = trimSlash(String(v));
  for (var k in SITES) {
    if (trimSlash(SITES[k]) === v) { base = v; break; }
  }
}
base + "/search/?q=" + key + "&page=" + page

